import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n)]
    idx = 1
    for _ in range(n - 1):
        a = data[idx] - 1
        b = data[idx + 1] - 1
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    parent = [-1] * n
    order = [0]
    for u in order:
        for v in adj[u]:
            if v == parent[u]:
                continue
            parent[v] = u
            order.append(v)

    down = [1] * n
    for u in reversed(order):
        vals = [down[v] for v in adj[u] if parent[v] == u]
        if len(vals) >= 3:
            vals.sort(reverse=True)
            down[u] = 1 + vals[0] + vals[1] + vals[2]

    up = [0] * n
    ans = -1

    for u in order:
        incoming = []
        for v in adj[u]:
            if v == parent[u]:
                incoming.append((v, up[u]))
            else:
                incoming.append((v, down[v]))

        incoming.sort(key=lambda x: x[1], reverse=True)
        m = len(incoming)

        if m >= 4:
            top4_sum = sum(incoming[i][1] for i in range(4))
            ans = max(ans, 1 + top4_sum)

            top3_sum = sum(incoming[i][1] for i in range(3))
            first3 = {incoming[i][0]: incoming[i][1] for i in range(3)}

            for v in adj[u]:
                if parent[v] == u:
                    if v in first3:
                        up[v] = 1 + top4_sum - first3[v]
                    else:
                        up[v] = 1 + top3_sum
        else:
            for v in adj[u]:
                if parent[v] == u:
                    up[v] = 1

    print(ans)

if __name__ == "__main__":
    main()
